window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-77b697d085a646c8"]={"versions": [{"id": "FIG-77b697d085a646c8", "releases": ["R1.5.1", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Nachrichtenflussdiagramm zur Zeitsynchronisation über Ethernet im AUTOSAR Time Synchronization Protocol (PRS_TimeSyncProtocol). Das Diagramm visualisiert den Anwendungsfall einer Time-Aware Bridge (gemäß IEEE 802.1AS / TSN-Kontext), bei der der Grandmaster (GTM / Grandmaster Clock) extern angebunden ist und nicht die interne Management-CPU der Bridge darstellt. Dargestellt werden die relevanten Hardware- und Software-Ebenen der Bridge, physikalische Switch-Ports sowie die Erfassungspunkte (Timestamping Points) für <code>Sync</code>- und <code>Follow_Up</code>-Nachrichten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Komponenten und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><strong>GTM (Grandmaster)</strong>: Externe Zeitquelle mit eigener lokaler Zeitbasis T_0.\n</li><li><strong>TimeSlave / Bridge</strong>: Zusammengesetzte Netzknoteneinheit bestehend aus:\n<ul class=\"fig-list\"><li><strong>Switch</strong>: Ethernet-Switching-Core mit mehreren Ports (<code>1</code>, <code>2</code>, <code>3</code>, <code>4</code>, <code>...</code>).\n</li><li><strong>Management CPU</strong>: Host-Prozessor zur Protokollverarbeitung mit Zeitbasis T_0&#x27;.\n</li></ul>\n</li><li><strong>TimeSlave</strong>: Externe Zeitnehmer-Knoten (ein aktiver TimeSlave mit lokaler Zeitbasis T_0&#x27;&#x27; an Port 2 sowie ein weiterer passiver/optionaler TimeSlave-Knoten).\n</li><li><strong>Ports &amp; Verbindungen</strong>:\n<ul class=\"fig-list\"><li>Port <code>3</code>: Ingress-Port für Nachrichten vom GTM.\n</li><li>Port <code>1</code>: Port zur Anbindung der internen Management-CPU.\n</li><li>Port <code>2</code>: Egress-Port zum angeschlossenen externen TimeSlave.\n</li></ul>\n</li><li><strong>Zeitstempelpunkte (Timestamping Points)</strong>:\n<ul class=\"fig-list\"><li>T_4: Ingress-Zeitstempel bei Empfang der Sync-Nachricht an Port 3.\n</li><li>T_5: Zeitstempel bei Übergabe/Empfang an der Management-CPU.\n</li><li>T_6: Zeitstempel bei Weiterleitung/Senden von der Management-CPU an Port 1.\n</li><li>T_7: Egress-Zeitstempel beim Verlassen des Switch-Ports 2.\n</li><li>T_c: Korrekturzeit / Ingress-Zeitstempel auf Empfängerseite am TimeSlave.\n</li><li>Zeitbasen: T_0 (GTM), T_0&#x27; (Management CPU), T_0&#x27;&#x27; (TimeSlave).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Nachrichtenfluss für <code>Sync</code> / <code>Follow_Up</code> verläuft asymmetrisch über die Bridge:</p>\n<ol class=\"fig-list\"><li>Der <strong>GTM</strong> initiiert die Synchronisationssequenz und sendet eine <code>Sync</code>-Nachricht an Port 3 des Switches. Am Ingress von Port 3 wird der Zeitstempel T_4 erfasst.\n</li><li>Der Switch leitet die Nachricht von Port 1 an die <strong>Management CPU</strong> weiter (Erfassung von Zeitstempel T_5).\n</li><li>Die Management CPU verarbeitet die Nachricht und speist sie über Port 1 wieder in den Switch ein (Erfassung von Zeitstempel T_6).\n</li><li>Der Switch leitet den Rahmen an den Ziel-Port 2 weiter. Beim Verlassen von Port 2 in Richtung des Ziel-TimeSlaves wird der Egress-Zeitstempel T_7 registriert.\n</li><li>Der <strong>TimeSlave</strong> empfängt die Nachricht und erfasst den Ankunftszeitstempel T_c (sowie die Referenzierung auf die lokale Zeit T_0&#x27;&#x27;).\n</li><li>Begleitende <code>Follow_Up</code>-Nachrichten transportieren die erfassten Präzisionszeitstempel zur Berechnung der Verweilzeit (Residence Time) und des Phasenversatzes.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm konkretisiert die normative Anforderung <code>[PRS_TS_00059]</code>. Bei der Implementierung einer Time Aware Bridge mit separater Management-CPU müssen Treiber (<code>Eth</code>, <code>EthSwt</code>) und der Protokoll-Stack (<code>EthTSyn</code>) sicherstellen, dass Ingress- (T_4) und Egress-Zeitstempel (T_7) der physikalischen Switch-Ports zusammen mit den Verarbeitungsstempeln der Host-CPU (T_5, T_6) korrekt korreliert werden. Dies ermöglicht die exakte Berechnung der internen Bridge-Latenz (Residence Time Correction) im PTP/gPTP-Header bzw. der <code>Follow_Up</code>-Nachricht, um Jitter und Pufferverzögerungen des internen Switches und Stacks zu kompensieren.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8af7e7029febba0d", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Nachrichtenflussdiagramm zur Zeitsynchronisation über Ethernet im AUTOSAR Time Synchronization Protocol (PRS_TimeSyncProtocol). Das Diagramm visualisiert den Anwendungsfall einer Time-Aware Bridge (gemäß IEEE 802.1AS / TSN-Kontext), bei der der Grandmaster (GTM / Grandmaster Clock) extern angebunden ist und nicht die interne Management-CPU der Bridge darstellt. Dargestellt werden die relevanten Hardware- und Software-Ebenen der Bridge, physikalische Switch-Ports sowie die Erfassungspunkte (Timestamping Points) für <code>Sync</code>- und <code>Follow_Up</code>-Nachrichten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Komponenten und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><strong>GTM (Grandmaster)</strong>: Externe Zeitquelle mit eigener lokaler Zeitbasis T_0.\n</li><li><strong>TimeSlave / Bridge</strong>: Zusammengesetzte Netzknoteneinheit bestehend aus:\n<ul class=\"fig-list\"><li><strong>Switch</strong>: Ethernet-Switching-Core mit mehreren Ports (<code>1</code>, <code>2</code>, <code>3</code>, <code>4</code>, <code>...</code>).\n</li><li><strong>Management CPU</strong>: Host-Prozessor zur Protokollverarbeitung mit Zeitbasis T_0&#x27;.\n</li></ul>\n</li><li><strong>TimeSlave</strong>: Externe Zeitnehmer-Knoten (ein aktiver TimeSlave mit lokaler Zeitbasis T_0&#x27;&#x27; an Port 2 sowie ein weiterer passiver/optionaler TimeSlave-Knoten).\n</li><li><strong>Ports &amp; Verbindungen</strong>:\n<ul class=\"fig-list\"><li>Port <code>3</code>: Ingress-Port für Nachrichten vom GTM.\n</li><li>Port <code>1</code>: Port zur Anbindung der internen Management-CPU.\n</li><li>Port <code>2</code>: Egress-Port zum angeschlossenen externen TimeSlave.\n</li></ul>\n</li><li><strong>Zeitstempelpunkte (Timestamping Points)</strong>:\n<ul class=\"fig-list\"><li>T_4: Ingress-Zeitstempel bei Empfang der Sync-Nachricht an Port 3.\n</li><li>T_5: Zeitstempel bei Übergabe/Empfang an der Management-CPU.\n</li><li>T_6: Zeitstempel bei Weiterleitung/Senden von der Management-CPU an Port 1.\n</li><li>T_7: Egress-Zeitstempel beim Verlassen des Switch-Ports 2.\n</li><li>T_c: Korrekturzeit / Ingress-Zeitstempel auf Empfängerseite am TimeSlave.\n</li><li>Zeitbasen: T_0 (GTM), T_0&#x27; (Management CPU), T_0&#x27;&#x27; (TimeSlave).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Nachrichtenfluss für <code>Sync</code> / <code>Follow_Up</code> verläuft asymmetrisch über die Bridge:</p>\n<ol class=\"fig-list\"><li>Der <strong>GTM</strong> initiiert die Synchronisationssequenz und sendet eine <code>Sync</code>-Nachricht an Port 3 des Switches. Am Ingress von Port 3 wird der Zeitstempel T_4 erfasst.\n</li><li>Der Switch leitet die Nachricht von Port 1 an die <strong>Management CPU</strong> weiter (Erfassung von Zeitstempel T_5).\n</li><li>Die Management CPU verarbeitet die Nachricht und speist sie über Port 1 wieder in den Switch ein (Erfassung von Zeitstempel T_6).\n</li><li>Der Switch leitet den Rahmen an den Ziel-Port 2 weiter. Beim Verlassen von Port 2 in Richtung des Ziel-TimeSlaves wird der Egress-Zeitstempel T_7 registriert.\n</li><li>Der <strong>TimeSlave</strong> empfängt die Nachricht und erfasst den Ankunftszeitstempel T_c (sowie die Referenzierung auf die lokale Zeit T_0&#x27;&#x27;).\n</li><li>Begleitende <code>Follow_Up</code>-Nachrichten transportieren die erfassten Präzisionszeitstempel zur Berechnung der Verweilzeit (Residence Time) und des Phasenversatzes.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm konkretisiert die normative Anforderung <code>[PRS_TS_00059]</code>. Bei der Implementierung einer Time Aware Bridge mit separater Management-CPU müssen Treiber (<code>Eth</code>, <code>EthSwt</code>) und der Protokoll-Stack (<code>EthTSyn</code>) sicherstellen, dass Ingress- (T_4) und Egress-Zeitstempel (T_7) der physikalischen Switch-Ports zusammen mit den Verarbeitungsstempeln der Host-CPU (T_5, T_6) korrekt korreliert werden. Dies ermöglicht die exakte Berechnung der internen Bridge-Latenz (Residence Time Correction) im PTP/gPTP-Header bzw. der <code>Follow_Up</code>-Nachricht, um Jitter und Pufferverzögerungen des internen Switches und Stacks zu kompensieren.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-77b697d085a646c8", "to": "FIG-8af7e7029febba0d", "fr": "R1.5.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8af7e7029febba0d", "to": "FIG-77b697d085a646c8", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
